import{_ as r,o,c as e,a2 as a}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Рабочее пространство","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/container.md","filePath":"ru/guides/container.md","lastUpdated":1792323081000}'),s={name:"ru/guides/container.md"};function n(l,t,i,d,h,g){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="рабочее-пространство" tabindex="-1">Рабочее пространство <a class="header-anchor" href="#рабочее-пространство" aria-label="Permalink to &quot;Рабочее пространство&quot;">​</a></h1><p>У каждого Bot есть собственное <strong>рабочее пространство</strong> — компьютер, который принадлежит ему: настоящая файловая система, терминал, выполняющий команды, предустановленный набор инструментов и, по желанию, видимый рабочий стол. Файлы, которые вы передаёте Bot, результаты, которые он производит, и инструменты, которые он устанавливает, живут здесь и сохраняются между сессиями.</p><h2 id="что-оно-умеет" tabindex="-1">Что оно умеет <a class="header-anchor" href="#что-оно-умеет" aria-label="Permalink to &quot;Что оно умеет&quot;">​</a></h2><ul><li>Хранить и редактировать файлы — просматривайте их в любой момент на вкладке <strong>Files</strong></li><li>Запускать скрипты и устанавливать пакеты: <strong>Node.js</strong> и <strong>Python</strong> предустановлены (<code>pip</code> и <code>uv</code> уже в PATH), настраивать интерпретатор не нужно</li><li>Держать фоновые задачи запущенными</li><li>Сохранять состояние между сессиями — вчерашняя незаконченная работа продолжается сегодня</li><li>По желанию — запускать видимый рабочий стол с браузером с графическим интерфейсом (headed)</li></ul><h2 id="где-оно-в-клиенте" tabindex="-1">Где оно в клиенте <a class="header-anchor" href="#где-оно-в-клиенте" aria-label="Permalink to &quot;Где оно в клиенте&quot;">​</a></h2><p>Несколько вкладок на странице Bot обращены к рабочему пространству:</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Содержимое</th></tr></thead><tbody><tr><td><strong>Workspace</strong></td><td>Состояние и жизненный цикл рабочего пространства: создание, запуск, остановка; сведения о среде, снапшоты, импорт и экспорт</td></tr><tr><td><strong>Files</strong></td><td>Просмотр и редактирование файловой системы рабочего пространства</td></tr><tr><td><strong>Terminal</strong></td><td>Интерактивная оболочка внутри рабочего пространства</td></tr><tr><td><strong>Desktop</strong></td><td>Видимый рабочий стол: живая картинка, перехват и возврат клавиатуры и мыши</td></tr><tr><td><strong>Network</strong></td><td>Состояние сети рабочего пространства</td></tr><tr><td><strong>Apps</strong></td><td>Приложения, установленные в это рабочее пространство, — навыки, зависимости, коннекторы (см. <a href="./supermarket.html">Supermarket</a>)</td></tr></tbody></table><h2 id="жизненныи-цикл" tabindex="-1">Жизненный цикл <a class="header-anchor" href="#жизненныи-цикл" aria-label="Permalink to &quot;Жизненный цикл&quot;">​</a></h2><p>Управляется с вкладки <strong>Workspace</strong>:</p><ul><li><strong>Create</strong> (создание): собирает новое рабочее пространство из шаблона, с индикатором прогресса.</li><li><strong>Start / Stop</strong> (запуск / остановка): останавливайте его, чтобы не тратить ресурсы в простое, — ничего не теряется.</li><li><strong>Delete</strong> (удаление): убирает запущенный экземпляр.</li></ul><p>Большинству возможностей — терминалу, рабочему столу, установке и обновлению приложений — нужно, чтобы рабочее пространство было <strong>запущено</strong>. На той же вкладке показаны сведения о среде: состояние, образ, число фоновых задач.</p><h2 id="видимыи-рабочии-стол" tabindex="-1">Видимый рабочий стол <a class="header-anchor" href="#видимыи-рабочии-стол" aria-label="Permalink to &quot;Видимый рабочий стол&quot;">​</a></h2><p>Вкладка <strong>Desktop</strong> включает графический рабочий стол и показывает его. Когда он включён, Bot может управлять <strong>браузером с графическим интерфейсом (headed)</strong> внутри рабочего пространства, а панель рабочего стола показывает тот же экран, которым он оперирует:</p><ul><li>Наблюдайте каждый шаг вживую</li><li><strong>Перехватывайте</strong> клавиатуру и мышь в любой момент — ввести пароль, пройти CAPTCHA — и <strong>возвращайте управление</strong></li><li>Сессии браузера сохраняются в рабочем пространстве, так что следующая задача уже выполняется под вашим входом</li></ul><p>О различии на уровне инструментов см. <a href="./browser-computer-use.html">Browser / Computer Use</a>.</p><h2 id="снапшоты" tabindex="-1">Снапшоты <a class="header-anchor" href="#снапшоты" aria-label="Permalink to &quot;Снапшоты&quot;">​</a></h2><p><strong>Create Snapshot</strong> записывает текущее состояние рабочего пространства — точка отката перед большим изменением; <strong>Restore</strong> возвращает к выбранному снапшоту, а ненужные снапшоты можно удалять.</p><h2 id="импорт-и-экспорт" tabindex="-1">Импорт и экспорт <a class="header-anchor" href="#импорт-и-экспорт" aria-label="Permalink to &quot;Импорт и экспорт&quot;">​</a></h2><ul><li><strong>Export Data</strong>: упаковать файлы рабочего пространства для скачивания.</li><li><strong>Import Data</strong>: загрузить архив и распаковать его в рабочее пространство.</li><li><strong>Reset</strong>: вернуть каталог данных в чистое состояние — когда файловая система разгромлена или хочется начать заново.</li></ul><div class="tip custom-block"><p class="custom-block-title">Самостоятельное развёртывание</p><p>На какой среде выполнения работает рабочее пространство (containerd, Docker, Apple container, доверенный локальный каталог) и как в него пробрасываются устройства хоста, например GPU, — это вопросы развёртывания на стороне сервера, см. <a href="./../self-hosted/workspace-backends.html">Бэкенды рабочих пространств</a>. Пользователям Memoh Cloud трогать это не нужно.</p></div>',20)])])}const u=r(s,[["render",n]]);export{c as __pageData,u as default};
